from itertools import product
def ideals(n): return [sorted({(d*t)%n for t in range(n)}) for d in range(n) if d==0 or n%d==0]
def homs_to_Z2(J,n):
    # Z/n-linear maps J -> Z/2 (Z/2 as Z/n-module, n even): f(r*j) = r*f(j)
    out=[]
    for vals in product(range(2),repeat=len(J)):
        f=dict(zip(J,vals))
        if all(f[(a+b)%n]==(f[a]+f[b])%2 for a in J for b in J) and all(f[(r*a)%n]==(r*f[a])%2 for r in range(n) for a in J):
            out.append(f)
    return out
def baer(n):
    for J in ideals(n):
        for f in homs_to_Z2(J,n):
            if not any(all(f[j]==(j*x)%2 for j in J) for x in range(2)): return False
    return True
assert baer(6) and not baer(4)
